  `delay_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approaching_stop_id` bigint DEFAULT NULL,
  `total_pickups` int NOT NULL DEFAULT '0',
  `total_dropoffs` int NOT NULL DEFAULT '0',
